    CAVE = "cave"
    ANCIENT_RUINS = "ancient_ruins"

# Player abilities
class Ability(Enum):
    STRENGTH = "strength"      # Move heavy objects, break barriers
    AGILITY = "agility"        # Navigate tight spaces, avoid traps
    INTELLIGENCE = "intelligence"  # Solve puzzles, decode symbols
    STEALTH = "stealth"        # Avoid detection, disable traps silently

# Game Object Types
class ObjectType(Enum):
    PLAYER = "player"
    TREASURE = "treasure"
    OBSTACLE = "obstacle"
    PUZZLE = "puzzle"
    FINAL_TREASURE = "final_treasure"
    TRAP = "trap"

@dataclass
class Position:
    x: float
    y: float

    def distance_to(self, other: 'Position') -> float:
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2)

    def __hash__(self):
        return hash((self.x, self.y))

    def __eq__(self, other):
        return isinstance(other, Position) and self.x == other.x and self.y == other.y

@dataclass
class GameObject:
    obj_type: ObjectType
    position: Position
    team_id: Optional[int] = None
    is_active: bool = True
    metadata: dict = field(default_factory=dict)

