class Player(GameObject):
    ability: Ability
    inventory: List[str] = field(default_factory=list)
    health: int = 100
    speed: float = 2.0
    is_active: bool = True

    def can_solve_puzzle(self, puzzle: 'Puzzle') -> bool:
        return self.ability == puzzle.required_ability

