@dataclass
class Team:
    team_id: int
    players: List[Player] = field(default_factory=list)
    treasures_collected: int = 0
    time_to_final: Optional[float] = None
    is_finished: bool = False

    def add_player(self, player: Player):
        self.players.append(player)

    def score(self) -> float:
        # Score = treasures + time bonus (inverse of time taken)
        time_bonus = 0
        if self.time_to_final:
            time_bonus = max(0, GAME_DURATION - self.time_to_final) / GAME_DURATION * 100
        return self.treasures_collected * 10 + time_bonus

@dataclass
class GameState:
    teams: Dict[int, Team]
    environment: Environment
    players: Dict[int, Player]  # indexed by player_id
    active_players: Set[int]  # player_ids currently in game
    game_time: float = 0.0
    is_over: bool = False
    winner: Optional[int] = None
    final_treasure: FinalTreasure = field(default_factory=lambda: FinalTreasure(ObjectType.FINAL_TREASURE, Position(0,0)))

    def __post_init__(self):
        # Ensure final treasure is placed
        if self.environment.final_chamber:
            self.final_treasure.position = self.environment.final_chamber

    def update(self, delta_time: float):
        self.game_time += delta_time
        if self.game_time >= GAME_DURATION:
            self.is_over = True
            self.determine_winner()

    def determine_winner(self):
        if not self.teams:
            return
        max_score = -1
        winners = []
        for team_id, team in self.teams.items():
            score = team.score()
            if score > max_score:
                max_score = score
                winners = [team_id]
            elif score == max_score:
                winners.append(team_id)
        self.winner = winners[0] if len(winners) == 1 else None  # tie if multiple

    def check_final_chamber_unlock(self):
        total_collected = sum(team.treasures_collected for team in self.teams.values())
        if total_collected >= self.final_treasure.required_treasures and not self.final_treasure.unlocked:
            self.final_treasure.unlocked = True
            print("Final Treasure Chamber has been unlocked!")

    def is_player_in_final_chamber(self, player: Player) -> bool:
        return player.position.distance_to(self.final_treasure.position) < 1.0

    def collect_treasure(self, player: Player, treasure: Treasure) -> bool:
        if treasure.collected or not treasure.is_active:
            return False
        treasure.collected = True
        treasure.is_active = False
        team = self.teams[player.team_id]
        team.treasures_collected += treasure.value
        self.check_final_chamber_unlock()
        return True

    def attempt_puzzle_solve(self, player: Player, puzzle: Puzzle) -> bool:
        if puzzle.solved or not puzzle.is_active:
            return False
        if player.can_solve_puzzle(puzzle):
            puzzle.solved = True
            puzzle.is_active = False
            # Find treasure reward
            reward_pos = Position(puzzle.position.x + random.randint(-1,1), puzzle.position.y + random.randint(-1,1))
            reward = Treasure(ObjectType.TREASURE, reward_pos, value=10)
            self.environment.treasures.append(reward)
            return True
        return False

    def trigger_trap(self, player: Player, trap: Trap) -> bool:
        if trap.triggered or not trap.is_active:
            return False
        if trap.stealth_required and player.ability != Ability.STEALTH:
            player.health -= trap.damage
            if player.health <= 0:
                player.is_active = False
            trap.triggered = True
            return True
        elif not trap.stealth_required:
            player.health -= trap.damage
            if player.health <= 0:
                player.is_active = False
            trap.triggered = True
            return True
        return False

    def move_player(self, player_id: int, dx: float, dy: float):
        if player_id not in self.active_players:
            return
        player = self.players[player_id]
        if not player.is_active:
            return
        new_x = player.position.x + dx * player.speed
        new_y = player.position.y + dy * player.speed
        new_pos = Position(new_x, new_y)

        # Boundary check
        if new_x < 0 or new_x >= self.environment.width or new_y < 0 or new_y >= self.environment.height:
            return

        # Collision with obstacles
        for obstacle in self.environment.obstacles:
            if obstacle.is_active and new_pos.distance_to(obstacle.position) < 1.0:
                if obstacle.is_breakable and player.ability == Ability.STRENGTH:
                    obstacle.is_active = False
                    player.position = new_pos
                    return
                else:
                    return  # Blocked

        # Collision with other players (simple collision avoidance)
        for other_player in self.players.values():
            if other_player != player and other_player.is_active and new_pos.distance_to(other_player.position) < 0.8:
                return  # Blocked by another player

        # Check for traps
        for trap in self.environment.traps:
            if trap.is_active and new_pos.distance_to(trap.position) < 1.0:
                self.trigger_trap(player, trap)
                return  # Trap triggered, don't move further

        # Update position
        player.position = new_pos

        # Check for treasure collection
        for treasure in self.environment.treasures:
            if treasure.is_active and not treasure.collected and new_pos.distance_to(treasure.position) < 0.8:
                self.collect_treasure(player, treasure)
                break

        # Check for puzzle interaction
        for puzzle in self.environment.puzzles:
            if puzzle.is_active and new_pos.distance_to(puzzle.position) < 0.8:
                self.attempt_puzzle_solve(player, puzzle)
                break

        # Check for final chamber
        if self.is_player_in_final_chamber(player):
            if self.final_treasure.unlocked and not self.teams[player.team_id].is_finished:
                self.teams[player.team_id].time_to_final = self.game_time
                self.teams[player.team_id].is_finished = True
                self.determine_winner()
                if self.is_over:
                    return


class GameEngine:
    def __init__(self):
        self.state: Optional[GameState] = None
        self.player_id_counter = 0
        self.command_queue = queue.Queue()
        self.lock = threading.Lock()

    def start_game(self, team_configs: List[List[Ability]]) -> bool:
        """
        team_configs: List of lists, each inner list is the abilities for players in that team.
        Example: [[Ability.STRENGTH, Ability.AGILITY], [Ability.INTELLIGENCE, Ability.STEALTH]]
        """
        if not team_configs or len(team_configs) > MAX_TEAMS:
            return False

        # Validate team sizes
        for team in team_configs:
            if len(team) > MAX_PLAYERS_PER_TEAM:
                return False

        # Create environment
        env_type = random.choice(list(EnvironmentType))
        environment = Environment.generate_env(env_type)

        # Create teams and players
        teams = {}
        players = {}
        active_players = set()

        for team_id, abilities in enumerate(team_configs):
            team = Team(team_id=team_id)
            teams[team_id] = team
            for ability in abilities:
                player = Player(
                    obj_type=ObjectType.PLAYER,
                    position=environment.spawn_points[self.player_id_counter],
                    team_id=team_id,
                    ability=ability,
                    health=100,
                    speed=2.0 + random.uniform(-0.2, 0.2)
                )
                players[self.player_id_counter] = player
                team.add_player(player)
                active_players.add(self.player_id_counter)
                self.player_id_counter += 1

        final_treasure = FinalTreasure(ObjectType.FINAL_TREASURE, environment.final_chamber)
        self.state = GameState(
            teams=teams,
            environment=environment,
            players=players,
            active_players=active_players,
            final_treasure=final_treasure
        )
        return True

    def process_player_command(self, player_id: int, command: str, args: List):
        """
        Process a command from a player
        Supported commands: 'move', 'solve', 'interact'
        """
        if player_id not in self.state.active_players:
            return False

        if command == "move":
            if len(args) != 2:
                return False
            dx, dy = args[0], args[1]
            self.state.move_player(player_id, dx, dy)
            return True

        elif command == "solve":
            # Player attempts to solve a puzzle nearby
            for puzzle in self.state.environment.puzzles:
                if puzzle.is_active and self.state.players[player_id].position.distance_to(puzzle.position) < 1.0:
                    self.state.attempt_puzzle_solve(self.state.players[player_id], puzzle)
                    return True
            return False

        elif command == "interact":
            # For debugging or future expansion
            return True

        return False

    def remove_player(self, player_id: int):
        """
        Handle a player leaving the game.
        """
        if player_id not in self.state.active_players:
            return False
        self.state.active_players.remove(player_id)
        self.state.players[player_id].is_active = False
        # Do not remove from teams immediately to preserve team scores
        return True

    def get_game_state(self):
        """
        Return a serializable state snapshot.
        """
        if not self.state:
            return None
        return {
            "game_time": self.state.game_time,
            "is_over": self.state.is_over,
            "winner": self.state.winner,
            "teams": {
                tid: {
                    "treasures_collected": team.treasures_collected,
                    "time_to_final": team.time_to_final,
                    "is_finished": team.is_finished,
                    "score": team.score(),
                    "players": [
                        {
                            "id": pid,
                            "ability": p.ability.value,
                            "health": p.health,
                            "position": (p.position.x, p.position.y),
                            "inventory": p.inventory
                        }
                        for pid, p in self.state.players.items() if p.team_id == tid and p.is_active
                    ]
                }
                for tid, team in self.state.teams.items()
            },
            "environment": {
                "type": self.state.environment.env_type.value,
                "final_chamber_unlocked": self.state.final_treasure.unlocked,
                "active_treasures": len([t for t in self.state.environment.treasures if t.is_active and not t.collected]),
                "active_puzzles": len([p for p in self.state.environment.puzzles if p.is_active and not p.solved]),
                "active_traps": len([t for t in self.state.environment.traps if t.is_active and not t.triggered])
            },
            "active_players": list(self.state.active_players)
        }

    def run_game_loop(self):
        """
        Simulate a real-time game loop (for testing or visualization).
        """
        if not self.state:
            return

        clock = pygame.time.Clock()
        screen = pygame.display.set_mode((SCREEN_WIDTH, SCREEN_HEIGHT))
        pygame.display.set_caption("Team Treasure Hunt")

        scale_x = SCREEN_WIDTH / self.state.environment.width
        scale_y = SCREEN_HEIGHT / self.state.environment.height

        while not self.state.is_over:
            # Handle commands
            while not self.command_queue.empty():
                player_id, command, args = self.command_queue.get()
                self.process_player_command(player_id, command, args)

            # Update game state
            self.state.update(1.0 / FPS)

            # Render
            screen.fill((0, 0, 0))
            self.render_game(screen, scale_x, scale_y)
            pygame.display.flip()
            clock.tick(FPS)

        # Game Over
        print(f"Game Over! Winner: Team {self.state.winner}")
        pygame.quit()

    def render_game(self, screen, scale_x, scale_y):
        if not self.state:
            return

        # Render environment
        for obstacle in self.state.environment.obstacles:
            if obstacle.is_active:
                pygame.draw.circle(screen, (139, 69, 19), 
                    (int(obstacle.position.x * scale_x), int(obstacle.position.y * scale_y)), 
                    int(10 * scale_x))

        for trap in self.state.environment.traps:
            if trap.is_active and not trap.triggered:
                pygame.draw.circle(screen, (255, 165, 0), 
                    (int(trap.position.x * scale_x), int(trap.position.y * scale_y)), 
                    int(8 * scale_x))

        for treasure in self.state.environment.treasures:
            if treasure.is_active and not treasure.collected:
                pygame.draw.circle(screen, (255, 215, 0), 
                    (int(treasure.position.x * scale_x), int(treasure.position.y * scale_y)), 
                    int(6 * scale_x))

        for puzzle in self.state.environment.puzzles:
            if puzzle.is_active and not puzzle.solved:
                pygame.draw.circle(screen, (128, 0, 128), 
                    (int(puzzle.position.x * scale_x), int(puzzle.position.y * scale_y)), 
                    int(12 * scale_x))

        # Render final treasure
        if self.state.final_treasure.unlocked:
            pygame.draw.circle(screen, (255, 255, 0), 
                (int(self.state.final_treasure.position.x * scale_x), int(self.state.final_treasure.position.y * scale_y)), 
                int(15 * scale_x))

        # Render players
        for player in self.state.players.values():
            if player.is_active:
                color = TEAM_COLORS[player.team_id]
                pygame.draw.circle(screen, color, 
                    (int(player.position.x * scale_x), int(player.position.y * scale_y)), 
                    int(8 * scale_x))
                # Draw ability icon (simplified)
                if player.ability == Ability.STRENGTH:
                    pygame.draw.circle(screen, (255, 0, 0), 
                        (int(player.position.x * scale_x), int(player.position.y * scale_y - 12 * scale_y)), 3)
                elif player.ability == Ability.AGILITY:
                    pygame.draw.polygon(screen, (0, 255, 0),
                        [(int(player.position.x * scale_x), int(player.position.y * scale_y - 12 * scale_y)),
                         (int(player.position.x * scale_x - 5 * scale_x), int(player.position.y * scale_y - 8 * scale_y)),
                         (int(player.position.x * scale_x + 5 * scale_x), int(player.position.y * scale_y - 8 * scale_y))])
                elif player.ability == Ability.INTELLIGENCE:
                    pygame.draw.rect(screen, (0, 0, 255),
                        pygame.Rect(int(player.position.x * scale_x - 4 * scale_x), int(player.position.y * scale_y - 12 * scale_y), 8 * scale_x, 8 * scale_y))
                elif player.ability == Ability.STEALTH:
                    pygame.draw.circle(screen, (128, 128, 128), 
                        (int(player.position.x * scale_x), int(player.position.y * scale_y - 12 * scale_y)), 3)

        # Display game info
        font = pygame.font.SysFont('Arial', 20)
        time_text = font.render(f"Time: {int(self.state.game_time)}s", True, (255, 255, 255))
        screen.blit(time_text, (10, 10))
        for team_id, team in self.state.teams.items():
            team_text = font.render(f"Team {team_id + 1}: {team.treasures_collected} treasures", True, TEAM_COLORS[team_id])
            screen.blit(team_text, (10, 40 + team_id * 20))

        if self.state.final_treasure.unlocked:
            unlocked_text = font.render("FINAL TREASURE UNLOCKED", True, (255, 255, 0))
            screen.blit(unlocked_text, (SCREEN_WIDTH - 250, 10))

        if self.state.is_over:
            winner_text = font.render(f"WINNER: Team {self.state.winner + 1 if self.state.winner is not None else 'TIE'}", True, (255, 255, 255))
            screen.blit(winner_text, (SCREEN_WIDTH//2 - 80, SCREEN_HEIGHT//2))

