MAX_HEALTH = 100
MAX_ENERGY = 100
REGEN_RATE = 0.1  # per tick
POWERUP_SPAWN_RATE = 0.02  # per tick
Hazard_DENSITY = 0.03  # 3% of map has hazards

# Weapon types
class WeaponType(Enum):
    RANGED = "ranged"
    MELEE = "melee"
    SUPPORT = "support"

# Agent roles
class Role(Enum):
