@dataclass
class Position:
    x: float
    y: float

    def distance_to(self, other: 'Position') -> float:
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2)

    def __hash__(self):
        return hash((round(self.x, 2), round(self.y, 2)))

    def __eq__(self, other):
        return isinstance(other, Position) and abs(self.x - other.x) < 1e-5 and abs(self.y - other.y) < 1e-5

@dataclass
class Agent:
    id: str
    team: int
    role: Role
    position: Position
    health: float = MAX_HEALTH
    energy: float = MAX_ENERGY
    weapon: WeaponType = WeaponType.RANGED
    speed: float = 1.0
    shield: float = 0.0
    is_alive: bool = True
    vision_range: int = VISION_RANGE
    last_seen_enemies: Dict[str, Position] = field(default_factory=dict)  # enemy_id -> position
    objectives: List[ObjectiveType] = field(default_factory=list)
    communication_history: List[Dict] = field(default_factory=list)
    active_powerups: Dict[PowerUpType, float] = field(default_factory=dict)  # powerup -> duration

    def update(self, dt: float):
        # Regenerate health and energy
        if self.health < MAX_HEALTH:
            self.health = min(MAX_HEALTH, self.health + REGEN_RATE * dt)
        if self.energy < MAX_ENERGY:
            self.energy = min(MAX_ENERGY, self.energy + REGEN_RATE * dt)

        # Update power-ups
        expired = []
        for powerup, duration in self.active_powerups.items():
            duration -= dt
            if duration <= 0:
                expired.append(powerup)
            else:
                self.active_powerups[powerup] = duration
        for powerup in expired:
            self.apply_powerup_effect(powerup, remove=True)

    def apply_powerup_effect(self, powerup: PowerUpType, remove: bool = False):
        if powerup == PowerUpType.SPEED_BOOST:
            if remove:
                self.speed /= 1.5
            else:
                self.speed *= 1.5
        elif powerup == PowerUpType.SHIELD:
            if remove:
                self.shield = 0
            else:
                self.shield = MAX_HEALTH * 0.5
        elif powerup == PowerUpType.HEAL:
            if not remove:
                self.health = min(MAX_HEALTH, self.health + 30)
        elif powerup == PowerUpType.VISION_EXTEND:
            if remove:
                self.vision_range = VISION_RANGE
            else:
                self.vision_range = VISION_RANGE * 2

    def add_communication(self, message: Dict):
        self.communication_history.append(message)

    def get_visible_agents(self, agents: List['Agent']) -> List['Agent']:
        visible = []
        for agent in agents:
            if agent.team == self.team:  # Friendly agents are always visible
                visible.append(agent)
            elif agent.is_alive and agent.team != self.team and self.position.distance_to(agent.position) <= self.vision_range:
                self.last_seen_enemies[agent.id] = agent.position
                visible.append(agent)
        return visible

    def move_toward(self, target: Position, obstacles: List[Position]) -> Position:
        direction = (target.x - self.position.x, target.y - self.position.y)
        distance = math.sqrt(direction[0]**2 + direction[1]**2)
        if distance == 0:
            return self.position
        unit_dir = (direction[0] / distance, direction[1] / distance)

        step_size = self.speed * (1 / GAME_TICK_RATE)
        new_x = self.position.x + unit_dir[0] * step_size
        new_y = self.position.y + unit_dir[1] * step_size
        new_pos = Position(new_x, new_y)

        # Simple collision avoidance with obstacles
        for obs in obstacles:
            if new_pos.distance_to(obs) < 1.0:
                # Try to dodge
                dodge_dirs = [(0,1), (1,0), (0,-1), (-1,0)]
                for dx, dy in dodge_dirs:
                    test_x = self.position.x + dx * step_size
                    test_y = self.position.y + dy * step_size
                    test_pos = Position(test_x, test_y)
                    if all(test_pos.distance_to(obs) >= 1.0 for obs in obstacles):
                        return test_pos
                return self.position  # Can't move

        # Boundary check
        new_x = max(1, min(MAP_SIZE[0]-1, new_x))
        new_y = max(1, min(MAP_SIZE[1]-1, new_y))
        return Position(new_x, new_y)

@dataclass
class GameMap:
    width: int = MAP_SIZE[0]
