    powerups: List[Dict] = field(default_factory=list)  # {position: Position, type: PowerUpType, active: bool}

    def __post_init__(self):
        self.tiles = [[TileType.EMPTY for _ in range(self.height)] for _ in range(self.width)]
        # Place walls on edges
        for x in range(self.width):
            self.tiles[x][0] = TileType.WALL
            self.tiles[x][self.height-1] = TileType.WALL
        for y in range(self.height):
            self.tiles[0][y] = TileType.WALL
            self.tiles[self.width-1][y] = TileType.WALL

        # Randomly place hazards
        for _ in range(int(self.width * self.height * Hazard_DENSITY)):
            x, y = random.randint(1, self.width-2), random.randint(1, self.height-2)
            if self.tiles[x][y] == TileType.EMPTY:
                self.tiles[x][y] = TileType.HAZARD
                self.hazards.append(Position(x, y))

        # Place bases and flags for each team
        team_positions = [(10,10), (10, self.height-10), (self.width-10,10), (self.width-10,self.height-10)]
        for i in range(min(MAX_TEAMS, 4)):
            if i < len(team_positions):
                x, y = team_positions[i]
