@dataclass
class AIController:
    game_state: GameState
    agent: Agent

    def decide_action(self) -> Dict[str, Any]:
        # Get visible agents and objects
        visible = self.agent.get_visible_agents(self.game_state.agents)
        teammates = [a for a in visible if a.team == self.agent.team]
        enemies = [a for a in visible if a.team != self.agent.team and a.is_alive]

