        elif self.agent.role == Role.DEFENDER:
            return self._defender_strategy(enemies, teammates, objective)
        elif self.agent.role == Role.HEALER:
            return self._healer_strategy(teammates)

        return {"action": "wait"}

    def _scout_strategy(self, enemies: List[Agent], teammates: List[Agent]) -> Dict[str, Any]:
        if enemies:
            # Report enemy positions
            for enemy in enemies:
                self.agent.add_communication({"type": "enemy_spotted", "id": enemy.id, "position": (enemy.position.x, enemy.position.y)})
            # Move toward nearest enemy to gather intel
            target = min(enemies, key=lambda e: self.agent.position.distance_to(e.position)).position
            new_pos = self.agent.move_toward(target, self.game_state.map.hazards)
            return {"action": "move", "target": (new_pos.x, new_pos.y)}
        else:
