                return {"action": "move", "target": (new_pos.x, new_pos.y)}
            else:
                return {"action": "patrol"}

    def _attacker_strategy(self, enemies: List[Agent], teammates: List[Agent], objective: ObjectiveType) -> Dict[str, Any]:
        if objective == ObjectiveType.CAPTURE_FLAG:
            # Find enemy flag
            flag_pos = None
            for team, pos in self.game_state.map.flags.items():
                if team != self.agent.team:
                    flag_pos = pos
                    break
            if flag_pos:
                # Move toward flag
                new_pos = self.agent.move_toward(flag_pos, self.game_state.map.hazards)
                return {"action": "move", "target": (new_pos.x, new_pos.y)}
        elif objective == ObjectiveType.ELIMINATE_ENEMIES:
            if enemies:
                target = min(enemies, key=lambda e: self.agent.position.distance_to(e.position))
                if self.agent.position.distance_to(target.position) <= COMBAT_RANGE:
                    return {"action": "attack", "target": target.id}
                else:
                    new_pos = self.agent.move_toward(target.position, self.game_state.map.hazards)
                    return {"action": "move", "target": (new_pos.x, new_pos.y)}
        # Default: Attack nearest enemy
        if enemies:
            target = min(enemies, key=lambda e: self.agent.position.distance_to(e.position))
            if self.agent.position.distance_to(target.position) <= COMBAT_RANGE:
                return {"action": "attack", "target": target.id}
            else:
                new_pos = self.agent.move_toward(target.position, self.game_state.map.hazards)
                return {"action": "move", "target": (new_pos.x, new_pos.y)}

        # If no enemies, move toward enemy base
        base_pos = None
        for team, pos in self.game_state.map.bases.items():
            if team != self.agent.team:
                base_pos = pos
                break
        if base_pos:
            new_pos = self.agent.move_toward(base_pos, self.game_state.map.hazards)
            return {"action": "move", "target": (new_pos.x, new_pos.y)}

        return {"action": "wait"}

    def _defender_strategy(self, enemies: List[Agent], teammates: List[Agent], objective: ObjectiveType) -> Dict[str, Any]:
        # Defend base
        base_pos = self.game_state.map.bases[self.agent.team]

        if enemies:
            # If enemy near base, engage
            for enemy in enemies:
                if enemy.position.distance_to(base_pos) < 20:
                    if self.agent.position.distance_to(enemy.position) <= COMBAT_RANGE:
                        return {"action": "attack", "target": enemy.id}
                    else:
                        new_pos = self.agent.move_toward(enemy.position, self.game_state.map.hazards)
                        return {"action": "move", "target": (new_pos.x, new_pos.y)}
            # If no enemy near base, stay near base
            new_pos = self.agent.move_toward(base_pos, self.game_state.map.hazards)
            return {"action": "move", "target": (new_pos.x, new_pos.y)}
        else:
            # Patrol around base
            patrol_points = [
                Position(base_pos.x + 5, base_pos.y),
                Position(base_pos.x, base_pos.y + 5),
                Position(base_pos.x - 5, base_pos.y),
                Position(base_pos.x, base_pos.y - 5)
            ]
            # Choose next patrol point
            closest_point = min(patrol_points, key=lambda p: self.agent.position.distance_to(p))
            new_pos = self.agent.move_toward(closest_point, self.game_state.map.hazards)
            return {"action": "move", "target": (new_pos.x, new_pos.y)}

    def _healer_strategy(self, teammates: List[Agent]) -> Dict[str, Any]:
        # Find lowest health teammate
        lowest_health = float('inf')
        target_teammate = None
        for teammate in teammates:
            if teammate != self.agent and teammate.health < lowest_health and teammate.health < MAX_HEALTH * 0.5:
                lowest_health = teammate.health
                target_teammate = teammate

        if target_teammate:
            if self.agent.position.distance_to(target_teammate.position) <= MELEE_RANGE:
                # Use heal ability
                self.agent.energy -= 10
                target_teammate.health = min(MAX_HEALTH, target_teammate.health + 20)
                self.agent.add_communication({"type": "healed", "target": target_teammate.id})
                return {"action": "heal", "target": target_teammate.id}
            else:
                # Move toward teammate
                new_pos = self.agent.move_toward(target_teammate.position, self.game_state.map.hazards)
                return {"action": "move", "target": (new_pos.x, new_pos.y)}
        else:
            # Find nearest teammate and stay nearby
            if teammates:
                nearest = min(teammates, key=lambda t: self.agent.position.distance_to(t.position))
                new_pos = self.agent.move_toward(nearest.position, self.game_state.map.hazards)
                return {"action": "move", "target": (new_pos.x, new_pos.y)}
        return {"action": "patrol"}

@dataclass
class TeamTacticsGame:
    def __init__(self):
        self.map = GameMap()
        self.agents: List[Agent] = []
        self.game_state = GameState(self.map, self.agents, [ObjectiveType.CAPTURE_FLAG, ObjectiveType.DEFEND_BASE, ObjectiveType.ELIMINATE_ENEMIES])
        self.ai_controllers: Dict[str, AIController] = {}
        self.game_running = False
        self.lock = threading.Lock()

    def spawn_agents(self, team_configs: List[Dict]):
        # team_configs: list of dicts with keys: team_id, role, count
        agent_id = 0
        for config in team_configs:
            team_id = config["team_id"]
            role = config["role"]
            count = config["count"]
            for _ in range(count):
                # Spawn near base
                base_pos = self.map.bases[team_id]
                offset_x = random.randint(-3, 3)
                offset_y = random.randint(-3, 3)
                pos = Position(base_pos.x + offset_x, base_pos.y + offset_y)

                agent = Agent(
                    id=f"agent_{agent_id}",
                    team=team_id,
                    role=role,
                    position=pos
                )
                self.agents.append(agent)
                self.ai_controllers[agent.id] = AIController(self.game_state, agent)
                agent_id += 1

    def run_tick(self):
        with self.lock:
            if not self.game_running:
                return

            # Update game state
            dt = 1.0 / GAME_TICK_RATE
            self.game_state.update(dt)

            # AI decisions
            for agent in self.agents:
                if agent.is_alive:
                    controller = self.ai_controllers[agent.id]
                    action = controller.decide_action()

                    # Execute action
                    if action["action"] == "move":
                        target = Position(action["target"][0], action["target"][1])
                        agent.position = agent.move_toward(target, self.map.hazards)
                    elif action["action"] == "attack":
                        target_id = action["target"]
                        target_agent = next((a for a in self.agents if a.id == target_id), None)
                        if target_agent and target_agent.is_alive and agent.position.distance_to(target_agent.position) <= COMBAT_RANGE:
                            damage = 10
                            if agent.weapon == WeaponType.MELEE:
                                damage = 15
                            target_agent.health -= damage
                            if target_agent.health <= 0:
                                target_agent.is_alive = False
                                target_agent.add_communication({"type": "agent_killed", "killer": agent.id})
                    # Other actions (heal, etc.) are handled inside AIController

    def start_game(self):
        self.game_running = True

    def stop_game(self):
        self.game_running = False

    def get_game_status(self):
        return {
            "game_time": self.game_state.game_time,
            "tick": self.game_state.tick,
            "winner": self.game_state.winner,
            "team_scores": self.game_state.team_scores,
            "alive_agents": [a.id for a in self.agents if a.is_alive],
            "dead_agents": [a.id for a in self.agents if not a.is_alive],
            "objectives": [obj.value for obj in self.game_state.objectives]
        }

