def test_edge_case_stuck_agents():
    # Create a map with narrow passages
    game = TeamTacticsGame()
    game.map.tiles[50][50] = TileType.WALL
    game.map.tiles[50][51] = TileType.WALL
    game.map.tiles[51][50] = TileType.WALL
    game.map.tiles[51][51] = TileType.WALL

    game.spawn_agents([
        {"team_id": 0, "role": Role.ATTACKER, "count": 1}
    ])

    # Place agent right next to the wall block
    game.agents[0].position = Position(49, 50)

    game.start_game()
    for _ in range(50):
        game.run_tick()

    # Agent should not be stuck forever
    # Check if agent moved to avoid wall
    assert game.agents[0].position.y != 50 or game.agents[0].position.x != 49, "Agent should have moved to avoid obstacle"
    print("Test edge_case_stuck_agents: PASSED")

def test_edge_case_ability_interaction():
    game = TeamTacticsGame()
    game.spawn_agents([
        {"team_id": 0, "role": Role.HEALER, "count": 1},
        {"team_id": 0, "role": Role.ATTACKER, "count": 1}
    ])

