    game.agents[1].health = 20

    # Spawn shield powerup near attacker
    game.map.powerups.append({
        "position": game.agents[1].position,
        "type": PowerUpType.SHIELD,
        "active": True
    })

    # Run tick to collect powerup
    game.run_tick()

    # Run tick to heal
    game.run_tick()

    # Attacker should have shield AND healed
    attacker = game.agents[1]
    assert attacker.shield > 0, "Attacker should have shield"
    assert attacker.health > 20, "Attacker should be healed"
    print("Test edge_case_ability_interaction: PASSED")

